"rb_unraid_disks":{"message0":"Unraid diskⱏi","tooltip":"Spisⱏkⱏ zapisii, po edinⱏ za vseakⱏ diskⱏ v l(i)cye, prⱐveye ravⱐstvo, potomⱏ danⱐe, potomⱏ sⱏkrovishche: name, type, status (DISK_OK, DISK_NP, ...), temp_c, errors, size_gb i free_gb."},
"rb_unraid_shares":{"message0":"Unraid delⱏi","tooltip":"Spisⱏkⱏ zapisii, po edinⱏ za vseakⱏ delⱏ poznikovⱏ: name, free_gb, used_gb i total_gb."},
"rb_unraid_containers":{"message0":"Unraid sosudⱏi","tooltip":"Spisⱏkⱏ zapisii, po edinⱏ za vseakⱏ Docker sosudⱏ: name, state (running, exited, ...), status i auto_start (ache Unraid ego s likomⱏ nachalⱏ bystⱏ)."},
"rb_unraid_vms":{"message0":"Unraid mashiny","tooltip":"Spisⱏkⱏ zapisii, po edinⱏ za vseakou vidⱐnou mashinou: name i state (RUNNING, SHUTOFF, ...)."},
"rb_unraid_container_power":{"message0":"%1 Unraid sosudⱏ %2","tooltip":"Nachnetⱏ ili vospatitⱏ edinⱏ Docker sosudⱏ, po imene. Te voprahaetⱏ vsegda prⱐveye, asche i nichⱐto zhe ino ne voprahaetⱏ, i ne sⱏshⱅou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐto zhe istino ne nachnetⱏ se ni vospatitⱏ."},
"rb_unraid_vm_power":{"message0":"%1 Unraid mashina %2","tooltip":"Nachnetⱏ ili vospatitⱏ edinou vidⱐnou mashinou, po imene. Te voprahaetⱏ vsegda prⱐveye, asche i nichⱐto zhe ino ne voprahaetⱏ, i ne sⱏshⱅou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐto zhe istino ne nachnetⱏ se ni vospatitⱏ."},
"rb_unraid_parity":{"message0":"ispytati ravⱐstvo Unraid","tooltip":"Ispytayetⱏ ravⱐstvenⱏi diskⱏi chtⱏi ihⱏ, ne pisatⱏ ispravlenⱐe. Te voprahaetⱏ vsegda prⱐveye, asche i nichⱐto zhe ino ne voprahaetⱏ, i ne sⱏshⱅou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐto zhe istino ne ispytaetⱏ se."},
