"rb_pihole_top_domains":{"message0":"naibolee zagrajdenyja domeny %1","tooltip":"Spisakⱏ zapisii, po edinⱏ za vseaky naibolee zagrajdenyii domenⱏ: domain i count (koli razⱏ zagrajdenⱏ). Toliko chtetⱏ."},
"rb_pihole_top_clients":{"message0":"glavnyja klienty %1","tooltip":"Spisakⱏ zapisii, po edinⱏ za vseako ustroistvo, ezhe vⱏproshaetⱏ naibolee: name, ip i count (koli vⱏprosovⱏ). Toliko chtetⱏ."},
"rb_pihole_blocking":{"message0":"iskliuchiti zagrajdenie Pi-hole na %1 sekundⱏ","tooltip":"Iskliuchaetⱏ zagrajdenie na tolmi sekundⱏ, posliezhe Pi-hole samo vⱏkljuchaetⱏ ego. Te voprahaetⱏ vsegda prⱏveye, asche i nichⱐcto zhe ino ne voprahaetⱏ, i ne sⱏshtou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐcto zhe istino ne mieniaetⱏ se."},
"rb_pihole_enable":{"message0":"vⱏkljuchiti zagrajdenie Pi-hole","tooltip":"Vⱏkljuchaetⱏ zagrajdenie vⱏspiatⱏ. Te voprahaetⱏ vsegda prⱏveye, asche i nichⱐcto zhe ino ne voprahaetⱏ, i ne sⱏshtou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐcto zhe istino ne mieniaetⱏ se."},
"rb_pihole_allow":{"message0":"%1 %2 na allow listie Pi-hole","tooltip":"Polagaetⱏ domenⱏ na allow listu, ili emlⱏetⱏ. Te voprahaetⱏ vsegda prⱏveye, asche i nichⱐcto zhe ino ne voprahaetⱏ, i ne sⱏshtou chlovekou rekshou da, ne byvaetⱏ. Na sei stranici nichⱐcto zhe istino ne mieniaetⱏ se."},
